function readStop(stops, index) {
  if (index < 0 || index > stops.length) {
    return null;
  }
  return stops[index];
}

function totalCheckouts(counts) {
  let total = 0;
  for (let index = 1; index < counts.length; index += 1) {
    total += counts[index];
  }
  return total;
}

function selectReadyBatches(counts, minimum) {
  return counts.filter((count) => count > minimum);
}

function makeRepairOrder(issue, minutes, urgent) {
  return { issue, minutes, urgent: String(urgent) };
}

function listReadyPickups(parcels) {
  const ready = parcels.filter((parcel) => parcel.ready);
  return ready;
}
